    internal static XtDocument Encode(XtSchemaDefinition schema,XtBrepModel model,string identity)
    {
        var major=schema.ModelerVersion/100000;
        if(major is <30 or >38)throw new XtFormatException(XtErrorCode.UnsupportedVersion,$"Canonical B-rep encoding is supported for V30-V38, not {schema.Identity}.");
        var ids=new Ids(model);var nodes=new List<XtNode>(ids.Next);
        AddParts(schema,model,ids,nodes);AddBodies(schema,model,ids,nodes);AddTopology(schema,model,ids,nodes);AddGeometry(schema,model,ids,nodes);AddFrames(schema,model,ids,nodes);AddAssembly(schema,model,ids,nodes);AddMeshes(schema,model,ids,nodes);AddAttributes(schema,model,ids,nodes);
        ApplyUserFields(model,ids,nodes);
        ApplyTransmitOrder(model,nodes);
        var roots=new List<XtNodeIndex>();for(var i=0;i<model.Parts.Length;i++)if(model.Parts[i].IsRoot!=0)roots.Add(ids.Parts[i]);
        if(roots.Count==0&&model.Parts.Length!=0)roots.Add(ids.Parts[0]);
        if(roots.Count==0)throw new XtFormatException(XtErrorCode.ModelInvalid,"B-rep contains no part root.");
        if(roots.Count>1)
        {
            var block=Create(schema,"PART_XMT_BLOCK",ids.Container,roots.Count);Set(block,schema,"n_entries",XtFieldValue.Int(roots.Count));SetArray(block,schema,"entries",roots.Select(XtFieldValue.Ptr).ToArray());nodes.Insert(0,block);
        }
        else MoveFirst(nodes,roots[0]);
        return new XtDocument{VersionText=model.VersionText??$": TRANSMIT FILE created by ProjectGmKernel.Xt for modeller version {schema.ModelerVersion}",HeaderSchemaIdentity=identity,Schema=schema,UserFieldSize=UserFieldSize(model),Nodes=nodes.ToArray()};
    }

    private static void AddParts(XtSchemaDefinition s,XtBrepModel m,Ids ids,List<XtNode> nodes)
    {
        for(var i=0;i<m.Parts.Length;i++)
        {
            var row=m.Parts[i];var name=row.Kind==XtPartKind.Body?"BODY":"ASSEMBLY";var node=Create(s,name,ids.Parts[i]);
            Set(node,s,"node_id",XtFieldValue.Int(ids.Parts[i]));Set(node,s,"next",XtFieldValue.Ptr(row.HasExternalNext!=0?(row.ExternalNext>0?row.ExternalNext:ids.External):Id(ids.Parts,row.Next)));Set(node,s,"previous",XtFieldValue.Ptr(row.HasExternalPrevious!=0?(row.ExternalPrevious>0?row.ExternalPrevious:ids.External):Id(ids.Parts,row.Previous)));nodes.Add(node);
        }
    }
