            Set(node,s,"highest_node_id",XtFieldValue.Int(row.HighestNodeId>0?row.HighestNodeId:ids.Next));Set(node,s,"state",XtFieldValue.Unsigned(1));Set(node,s,"body_type",XtFieldValue.Unsigned(BodyType(row.Kind)));Set(node,s,"nom_geom_state",XtFieldValue.Unsigned(1));Set(node,s,"owner",XtFieldValue.Ptr(Id(ids.Bodies,row.Owner)));Set(node,s,"child",XtFieldValue.Ptr(Id(ids.Bodies,row.Child)));
            Set(node,s,"ref_instance",XtFieldValue.Ptr(Id(ids.Instances,row.ReferenceInstance)));
            Set(node,s,"region",XtFieldValue.Ptr(First(ids.Regions,row.Regions)));Set(node,s,"shell",XtFieldValue.Ptr(First(ids.Shells,row.Shells)));Set(node,s,"edge",XtFieldValue.Ptr(First(ids.Edges,row.Edges)));Set(node,s,"vertex",XtFieldValue.Ptr(First(ids.Vertices,row.Vertices)));
            Set(node,s,"surface",XtFieldValue.Ptr(Id(ids.Geometries,row.Surface)));Set(node,s,"curve",XtFieldValue.Ptr(Id(ids.Geometries,row.Curve)));Set(node,s,"point",XtFieldValue.Ptr(Id(ids.Points,row.Point)));
            Set(node,s,"boundary_surface",XtFieldValue.Ptr(Id(ids.Geometries,row.BoundarySurface)));Set(node,s,"boundary_curve",XtFieldValue.Ptr(Id(ids.Geometries,row.BoundaryCurve)));Set(node,s,"boundary_point",XtFieldValue.Ptr(Id(ids.Points,row.BoundaryPoint)));Set(node,s,"boundary_mesh",XtFieldValue.Ptr(Id(ids.Meshes,row.BoundaryMesh)));Set(node,s,"boundary_polyline",XtFieldValue.Ptr(Id(ids.Meshes,row.BoundaryPolyline)));
            Set(node,s,"res_size",XtFieldValue.RealValue(1000));Set(node,s,"res_linear",XtFieldValue.RealValue(1e-8));
            Set(node,s,"index_map_offset",XtFieldValue.Int(0));Set(node,s,"lowest_node_id",XtFieldValue.Int(row.LowestNodeId));
        }
    }
