        var data=Create(s,curve?"CURVE_DATA":"SURFACE_DATA",ids.SurfaceData[index]);Set(data,s,curve?"tint":"original_uint",XtFieldValue.IntervalValue(r.OriginalULow,r.OriginalUHigh));Set(data,s,"self_int",XtFieldValue.Unsigned(r.SelfIntersection));if(curve){Set(data,s,"t_start",CharOrNull(r.OriginalUStart));Set(data,s,"t_end",CharOrNull(r.OriginalUEnd));}else{Set(data,s,"original_vint",XtFieldValue.IntervalValue(r.OriginalVLow,r.OriginalVHigh));Set(data,s,"extended_uint",XtFieldValue.IntervalValue(r.ExtendedULow,r.ExtendedUHigh));Set(data,s,"extended_vint",XtFieldValue.IntervalValue(r.ExtendedVLow,r.ExtendedVHigh));Set(data,s,"original_u_start",CharOrNull(r.OriginalUStart));Set(data,s,"original_u_end",CharOrNull(r.OriginalUEnd));Set(data,s,"original_v_start",CharOrNull(r.OriginalVStart));Set(data,s,"original_v_end",CharOrNull(r.OriginalVEnd));Set(data,s,"extended_u_start",CharOrNull(r.ExtendedUStart));Set(data,s,"extended_u_end",CharOrNull(r.ExtendedUEnd));Set(data,s,"extended_v_start",CharOrNull(r.ExtendedVStart));Set(data,s,"extended_v_end",CharOrNull(r.ExtendedVEnd));}nodes.Add(data);Set(surface,s,"nurbs",XtFieldValue.Ptr(nurbs.Index));Set(surface,s,"data",XtFieldValue.Ptr(data.Index));
