    private static XtNode ScalarNode(XtSchemaDefinition s,string nodeName,string fieldName,XtNodeIndex id,XtBrepModel m,XtRange range){var n=Create(s,nodeName,id,range.Count);var values=new XtFieldValue[range.Count];for(var i=0;i<values.Length;i++){var value=m.Scalars[range.Offset+i];values[i]=value.Present!=0?(nodeName=="KNOT_MULT"?XtFieldValue.Int((long)value.Value):XtFieldValue.RealValue(value.Value)):XtFieldValue.Null();}SetArray(n,s,fieldName,values);return n;}
    private static XtFieldValue CharOrNull(char value)=>value=='\0'?XtFieldValue.Null():XtFieldValue.Char(value);
